import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.logging.*;

public class AssetSearchServlet extends HttpServlet {
    private static final Logger log = Logger.getLogger(AssetSearchServlet.class.getName());
    private static final String DB_URL = "jdbc:postgresql://db-internal:5432/assets";
    private static final String DB_USER = "app_readonly";
    private static final String DB_PASS = System.getenv("DB_PASS");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String category = req.getParameter("category");
        String sortCol = req.getParameter("sort");
        String direction = req.getParameter("dir");

        if (category == null || category.isEmpty()) {
            resp.sendError(400, "Missing category parameter");
            return;
        }

        // Validate sort direction
        if (direction != null && !direction.equalsIgnoreCase("ASC") && !direction.equalsIgnoreCase("DESC")) {
            direction = "ASC";
        }

        // Allowlist for sort columns
        String[] allowedSorts = {"name", "created_at", "value", "location"};
        boolean validSort = false;
        if (sortCol != null) {
            for (String allowed : allowedSorts) {
                if (allowed.equals(sortCol)) {
                    validSort = true;
                    break;
                }
            }
            if (!validSort) sortCol = "name";
        } else {
            sortCol = "name";
        }

        // Build query - category is user-controlled
        String query = "SELECT id, name, value, location, created_at FROM assets WHERE category = '" 
                       + category + "' ORDER BY " + sortCol + " " + direction;

        log.info("Executing query for category: " + category);

        resp.setContentType("application/json");
        PrintWriter out = resp.getWriter();

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             Statement stmt = conn.createStatement()) {

            stmt.setQueryTimeout(5);
            ResultSet rs = stmt.executeQuery(query);

            out.print("[\n");
            boolean first = true;
            while (rs.next()) {
                if (!first) out.print(",\n");
                first = false;
                out.printf("  {\"id\": %d, \"name\": \"%s\", \"value\": %.2f, \"location\": \"%s\", \"created_at\": \"%s\"}",
                    rs.getInt("id"),
                    rs.getString("name").replace("\"", "\\\""),
                    rs.getDouble("value"),
                    rs.getString("location").replace("\"", "\\\""),
                    rs.getTimestamp("created_at").toString());
            }
            out.print("\n]");
        } catch (SQLException e) {
            log.warning("Database error: " + e.getMessage());
            resp.sendError(500, "Internal error");
        }
    }

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        // POST creates new asset - requires auth token
        String authHeader = req.getHeader("Authorization");
        if (authHeader == null || !authHeader.startsWith("Bearer ")) {
            resp.sendError(401, "Unauthorized");
            return;
        }

        String name = req.getParameter("name");
        String category = req.getParameter("category");
        String value = req.getParameter("value");
        String location = req.getParameter("location");

        if (name == null || category == null || value == null) {
            resp.sendError(400, "Missing required fields");
            return;
        }

        String insertQuery = "INSERT INTO assets (name, category, value, location) VALUES (?, ?, ?, ?)";

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             PreparedStatement pstmt = conn.prepareStatement(insertQuery)) {
            pstmt.setString(1, name);
            pstmt.setString(2, category);
            pstmt.setDouble(3, Double.parseDouble(value));
            pstmt.setString(4, location);
            pstmt.executeUpdate();
            resp.setStatus(201);
        } catch (SQLException e) {
            log.warning("Insert error: " + e.getMessage());
            resp.sendError(500, "Internal error");
        } catch (NumberFormatException e) {
            resp.sendError(400, "Invalid value format");
        }
    }
}
